export const servicePages: Record<IndustrialServiceId, DecisionPage[]> = {
  lev: [
    {
      path: '/lev', title: 'LEV testing: a practical starting point', description: 'Understand when local exhaust ventilation needs examination, what a proper TExT includes and how to buy it well.', cardPrompt: 'Separate statutory testing from servicing and build the right brief.', eyebrow: 'LEV overview',
      intro: 'Local exhaust ventilation captures dust, fume, mist, vapour or gas close to where it is created. When LEV is used to control exposure under COSHH, it must be maintained and its performance periodically proven—not merely assumed because the fan runs.',
      decision: { heading: 'Start with the contaminant, source and control', summary: 'The practical threshold is whether equipment captures a hazardous airborne contaminant at or near its source. Fixed ductwork, a portable unit, a spray booth, a fume cupboard and extraction fitted to a tool can all be LEV; the label attached to the equipment is not decisive.', checks: ['Identify what is emitted during normal work, cleaning, maintenance and foreseeable failure.', 'List every LEV system and hood, including portable and on-tool units rather than only the main dust plant.', 'Find commissioning information, intended performance, previous TExT reports and unresolved defect actions.'], action: 'If the system controls exposure, plan the statutory examination against its current due date. If it is unclear whether the equipment is LEV, record that uncertainty and ask a competent examiner to scope it rather than assuming it is general ventilation.' },
      sections: [
        { heading: 'What the duty is trying to prove', body: 'COSHH regulation 9 requires control measures to remain in efficient working order, good repair and a clean condition. For LEV, the thorough examination and test checks whether the complete system is still delivering the control performance needed for the real process.', detail: 'HSE describes a physical examination, technical measurements and professional judgement. The outcome should connect measured performance to control effectiveness and provide prioritised actions—not just a sticker or fan-speed reading.' },
        { heading: 'The usual interval is a maximum, not a target', body: 'Most LEV plant is examined and tested at least every 14 months. Schedule 4 sets shorter intervals for specified high-wear or historically high-risk processes, and HSG258 advises more frequent testing where effectiveness is liable to deteriorate between visits.', points: ['Check the interval stated in the last report', 'Do not automatically add 14 months if a shorter interval applies', 'Keep routine performance checks between statutory examinations', 'Retain examination, test and repair records for at least five years'] },
        { heading: 'A useful deliverable', body: 'A good report identifies the system, process, contaminant, test points, intended benchmark, condition, measured performance, conclusion, defects, priorities and next due date. It should be understandable to the employer and usable at the next examination.', detail: 'Where commissioning data is missing, the quotation should say how the examiner will establish or qualify the benchmark. Missing information should not disappear into an unexplained pass or fail.' },
      ], sources: [levFaq, levHsg, coshh9, levIndg],
    },
    {
      path: '/lev/do-i-need-an-lev-test', title: 'Do I need an LEV thorough examination and test?', description: 'A decision aid for checking whether extraction equipment is likely to need a COSHH thorough examination and test.', cardPrompt: 'Check fixed, portable and on-tool extraction without relying on its name.', eyebrow: 'Decision guide',
      intro: 'If extraction is provided to control employee exposure to a substance hazardous to health, it is likely to sit within the COSHH maintenance and examination regime. The answer depends on what it captures and why it exists, not simply its size.',
      decision: { heading: 'Use a source-control threshold', summary: 'Ask whether work creates a hazardous airborne contaminant, whether the equipment captures it close to the source, and whether that control is relied on to keep exposure adequately controlled. A yes to all three is a strong indicator that LEV examination duties are relevant.', checks: ['Include wood and stone dust, welding fume, spray mist, vapours and process-generated contaminants.', 'Include equipment integrated into tools, portable extractors, booths and cabinets where they provide source capture.', 'Check unusual Schedule 4 processes and any shorter interval already set by a competent person.'], action: 'Inventory each system and extraction point, find the last TExT report and compare its due date with the current date. If there is no report, obtain competent scoping rather than treating a recent service invoice as examination evidence.' },
      sections: [
        { heading: 'Strong indicators', body: 'Dust or fume is visibly generated, a hood or nozzle is positioned near the process, workers rely on the extraction rather than respiratory protection alone, or a COSHH assessment names LEV as a control. These are procurement indicators, not a substitute for exposure assessment.', points: ['Welding and thermal-cutting fume', 'Machining or sanding wood and board', 'Grinding, polishing or cutting mineral and metal materials', 'Spraying, coating, mixing or laboratory containment'] },
        { heading: 'Commonly missed systems', body: 'Employers often inventory the main fan and filter but omit each connected hood, on-tool extraction, portable units, microbiological cabinets or small solder fume extractors. HSE expressly treats on-tool extraction as LEV.', detail: 'The examiner still needs to decide whether each item falls within the duty and which test method is appropriate. The buyer’s job is to disclose the equipment rather than pre-filter it out.' },
        { heading: 'When the answer may genuinely be no', body: 'General comfort ventilation that does not capture a hazardous contaminant at source may not be LEV. A system may also be redundant and formally isolated. Those facts should be established and documented rather than inferred from low usage or small size.', detail: 'Even where a statutory LEV TExT is not the right service, other COSHH, maintenance, workplace-ventilation or equipment duties can still apply.' },
      ], sources: [levFaq, coshh9, coshhSchedule4, levGlossary],
    },
    {
      path: '/lev/cost', title: 'What does LEV testing cost?', description: 'Understand the equipment and reporting factors behind an LEV test quote and the limits of published UK pricing.', cardPrompt: 'Turn system and hood counts into a comparable price request.', eyebrow: 'Cost guide',
      intro: 'LEV examination is usually priced around attendance, systems, hoods or extraction points, measurement complexity, available benchmark data and reporting. Floor area or employee count alone is a poor pricing basis.',
      decision: { heading: 'Ask for the visit and point-count logic separately', summary: 'A meaningful quotation identifies the number of complete LEV systems, connected extraction points, test conditions and report deliverables. If those counts are missing, a low headline figure may simply exclude part of the plant or rely on assumptions that will change on arrival.', checks: ['List each fan/system and every hood or extraction point connected to it.', 'State whether commissioning data, diagrams and previous readings are available.', 'Identify access equipment, shutdowns, multiple shifts, recirculation and higher-complexity controls.'], action: 'Send every provider the same equipment schedule and request a fixed scope showing attendance, point counts, reporting, travel, VAT, retesting and remedial-work exclusions. Compare the deliverable before comparing the fee.' },
      sections: [
        { heading: 'What normally moves the price', body: 'More systems create more complete physical and performance checks; more hoods create more measurements; missing benchmarks require additional investigation; complex filtration, recirculation, variable controls and access can extend the work.', points: ['Number of separately driven systems', 'Total hoods and test points', 'Availability of commissioning benchmarks', 'Complex controls or recirculated air', 'Travel, access, shutdown and reporting requirements'] },
        { heading: 'What the Vendor Atlas range includes', body: 'The calculator uses an attendance allowance, per-system amount, extraction-point increment, complexity allowance, missing-baseline allowance and additional-site amount. Each adjustment is displayed and the result is widened into a planning range.', detail: 'The model is calibrated against a small number of provider-published simple-system figures. It is not a national average and it does not claim that a complex industrial system can be priced from those examples without scoping.' },
        { heading: 'Keep repairs outside the comparison', body: 'The statutory examination identifies condition and performance. Filter replacement, fan or duct repair, hood redesign, balancing and retesting should be shown separately unless every bidder has been asked to include the same work.', detail: 'A provider able to repair systems may be useful, but the commercial interest and examination conclusion should remain visible. Ask who makes the pass/fail judgement and how recommendations are quality reviewed.' },
      ], sources: [levHsg, coshh9, levGlossary],
    },
    {
      path: '/lev/who-can-test-lev', title: 'Who can carry out an LEV thorough examination and test?', description: 'How to test an LEV examiner’s competence, method, equipment and report without treating one qualification as automatic approval.', cardPrompt: 'Ask for system-specific competence and a sample deliverable.', eyebrow: 'Supplier guide',
      intro: 'The law requires competence; it does not appoint Vendor Atlas or a single trade badge as the approval authority. The examiner needs enough theoretical knowledge, practical skill and experience to examine the particular system and interpret whether it controls the contaminant.',
      decision: { heading: 'Match competence to the system and decision', summary: 'A basic single-hood woodworking extractor, a recirculating filtration system, a spray booth and a laboratory containment device do not present identical measurement or judgement demands. Ask who will attend, what they have examined before and how their method follows HSG258.', checks: ['Request the named examiner’s training, relevant experience and current calibration evidence.', 'Ask for a redacted example report for a comparable system, not only a certificate template.', 'Confirm how benchmarks, missing commissioning data, defects and retests will be handled.'], action: 'Shortlist providers only after the proposed person and method are clear. Record public evidence as a lead, then verify named-person competence, insurance, capacity and conflicts directly before appointment.' },
      sections: [
        { heading: 'Useful evidence', body: 'BOHS P601 is a commonly cited proficiency qualification for thorough examination and testing, but the buying decision should also consider practical experience, process knowledge, calibrated instruments, report quality and the ability to make defensible professional judgements.', detail: 'Qualifications can support competence; they do not prove that every holder is current or experienced with every system. Ask for evidence relevant to the work actually being commissioned.' },
        { heading: 'Test the method before appointment', body: 'The proposal should address physical condition, intended performance, measurements, observation of the process, comparison with benchmark data, judgement of control and prioritised remedial actions.', points: ['Equipment list and identification method', 'Instrumentation and calibration', 'Operating conditions during testing', 'Report contents and defect priorities', 'Retest arrangements after remedial work'] },
        { heading: 'Independence and repairs', body: 'HSE does not prohibit the examiner’s organisation from maintaining or repairing equipment, but the employer still needs a competent, reliable judgement. Ask how the examination conclusion is separated from product sales and remedial quotations.', detail: 'A transparent provider can identify defects, explain evidence, offer repairs separately and permit retesting without presenting every recommendation as a mandatory purchase.' },
      ], sources: [levHsg, levFaq, levIndg, levGlossary],
    },
    {
      path: '/lev/lev-testing-vs-servicing', title: 'LEV testing vs servicing: what is the difference?', description: 'Understand why maintenance, servicing, routine checks and a statutory LEV thorough examination are related but not interchangeable.', cardPrompt: 'Check which document you actually have before assuming the duty is complete.', eyebrow: 'Comparison guide',
      intro: 'A service keeps equipment in working order. A thorough examination and test determines whether the complete control system is still effective and records that evidence. One visit can include both, but the deliverables and decisions must remain clear.',
      decision: { heading: 'Read the report, not the invoice heading', summary: 'A document labelled service, maintenance, certificate or inspection is not automatically a COSHH thorough-examination record. Look for identified hoods and test points, measured technical performance, comparison with intended or previous values, a conclusion on control and prioritised remedial actions.', checks: ['Does the record identify the complete system and each hood or capture point?', 'Are measurements, instruments, operating conditions and benchmarks visible?', 'Does it state whether control is effective, what must change and when the next TExT is due?'], action: 'If the evidence is missing, ask the contractor whether a complete HSG258-aligned TExT was performed and request the full report. If it was only servicing, commission the examination separately rather than relabelling the invoice.' },
      sections: [
        { heading: 'Routine checks', body: 'Operators and managers should make regular simple checks between formal examinations: airflow indicators, hood condition, unusual noise, damaged ducting and filter status. These help find deterioration early but do not replace the statutory TExT.', detail: 'HSG258 expects a logbook or equivalent record connecting checks, maintenance, repair and examinations over the system life.' },
        { heading: 'Servicing and maintenance', body: 'Servicing can include cleaning, belt adjustment, filter replacement, fan work, balancing and repairs. It is essential when needed and is part of maintaining the control measure in efficient working order.', detail: 'The service may restore performance, but without the full examination evidence it does not demonstrate that the system controls exposure as intended.' },
        { heading: 'Thorough examination and test', body: 'The TExT is a structured evidence exercise: inspect the complete system, measure performance, observe control where appropriate, compare with benchmark information, judge effectiveness, report defects and set the next date.', detail: 'Ask for separate line items when buying combined service and TExT work so that the statutory deliverable and any commercial repair recommendations remain auditable.' },
      ], sources: [levGlossary, levHsg, coshh9],
    },
  ],
  'pressure-systems': [
    {
      path: '/pressure-systems', title: 'Pressure systems and PSSR: a practical starting point', description: 'Understand written schemes, competent-person examinations and how to scope pressure-system compliance work.', cardPrompt: 'Map the system and establish whether a written scheme comes first.', eyebrow: 'PSSR overview',
      intro: 'PSSR manages the risk of stored energy released by pressure-system failure. Its central procurement sequence is straightforward even when the engineering is not: establish safe operating limits, create a suitable written scheme, then examine the covered parts in accordance with it.',
      decision: { heading: 'Start with the system and relevant fluid', summary: 'PSSR defines pressure systems and relevant fluids rather than listing every product name. Steam at any pressure, compressed or liquefied gas above 0.5 bar above atmospheric pressure, and pressurised hot water above 110°C are prominent indicators, but exclusions and system boundaries still require competent review.', checks: ['Identify vessels, associated pipework, protective devices and the fluid throughout the system.', 'Record operating pressure, temperature, safe limits, capacity and manufacturer information.', 'Find the written scheme, examination reports, maintenance history and changes since the last review.'], action: 'If a relevant-fluid indicator is present or the data is uncertain, do not operate on an assumed exemption. Ask a competent person to define the system boundary and confirm the written-scheme and examination requirements.' },
      sections: [
        { heading: 'The written scheme is a system-specific plan', body: 'Regulation 8 requires a suitable written scheme for the parts where failure could give rise to danger. It identifies what will be examined, how, how often and what preparation or safety measures are needed.', detail: 'A generic template is not enough. The scheme must reflect the actual vessels, pipework, protective devices, operating conditions, deterioration mechanisms and consequences.' },
        { heading: 'The examination follows the scheme', body: 'Regulation 9 requires the competent person to examine the covered parts within the intervals and according to the nature specified by the scheme, then produce a written report and address danger findings.', points: ['Confirm the scheme remains suitable before the work', 'Prepare and isolate equipment as the scheme requires', 'Provide records that help judge deterioration', 'Act on repairs and imminent-danger findings'] },
        { heading: 'Maintenance remains separate', body: 'The statutory examination is comparable to an MOT: it is not a substitute for regular operation, monitoring and maintenance. The dutyholder remains responsible for the system even when an external inspection organisation is appointed.', detail: 'A useful buying brief therefore states whether the requirement is scheme creation, scheme review, examination, maintenance preparation, non-destructive testing or a combination with clear responsibilities.' },
      ], sources: [pssrOverview, pssrUser, pssrWse, pssrAcop],
    },
    {
      path: '/pressure-systems/do-i-need-a-written-scheme', title: 'Do I need a written scheme of examination?', description: 'A decision aid for identifying obvious PSSR relevant-fluid and pressure-system signals before competent review.', cardPrompt: 'Check fluid, pressure, temperature and system components before answering.', eyebrow: 'Decision guide',
      intro: 'A written scheme is likely to be required before operating a qualifying pressure system when component failure could give rise to danger. Product labels such as compressor, boiler or refrigeration plant are useful clues, but the legal decision turns on the defined system and relevant fluid.',
      decision: { heading: 'Use a fluid–pressure–danger screen', summary: 'Establish whether there is a pressure system, whether it contains steam, gas above the relevant pressure threshold, high-temperature pressurised water or another relevant fluid, and whether failure of a covered part could give rise to danger. Missing data is a reason to investigate, not a no answer.', checks: ['Check maximum and normal pressure rather than relying on the current gauge reading.', 'Include safety valves and other protective devices, plus relevant vessels and pipework.', 'Check who is the user of an installed system or owner of a mobile system and whether a supplier has assumed any duties in writing.'], action: 'Collect the equipment plate data, drawings and safe limits, then ask a competent person to confirm scope. If a new qualifying system has no suitable scheme and examination, resolve that before putting it into operation.' },
      sections: [
        { heading: 'Strong indicators', body: 'Compressed-air receivers, steam boilers, autoclaves, refrigeration plant, pressure process vessels and commercial steam boilers frequently justify a PSSR check. The final scope can include more than the obvious vessel.', points: ['Steam at any pressure', 'Compressed or liquefied gas above 0.5 bar above atmosphere', 'Pressurised hot water above 110°C', 'Associated protective devices and safety-critical pipework'] },
        { heading: 'Why pressure alone is not the whole answer', body: 'PSSR includes definitions, exceptions and divisions of responsibility that cannot be reduced to a single gauge threshold. Hydraulic systems, transportable receptacles, pipelines and installed systems can follow different routes or other legislation.', detail: 'The finder therefore identifies clear indicators and uncertainties. It does not certify that a system is included or exempt.' },
        { heading: 'What to assemble for a decision', body: 'Provide the competent person with equipment schedules, pressure and temperature data, fluids, capacities, manufacturer information, drawings, protective devices, operating history, modifications and existing inspection documents.', detail: 'Incomplete information may require a site inventory before a scheme can be priced or certified. Put that discovery work explicitly into the quotation rather than assuming it is free.' },
      ], sources: [pssrOverview, pssrWse, pssrReg8, pssrBrief],
    },
    {
      path: '/pressure-systems/cost', title: 'What does a PSSR written scheme and examination cost?', description: 'Understand the plant, scheme, examination and access factors behind a pressure-system quotation.', cardPrompt: 'Separate scheme creation, examination and maintenance preparation in the price.', eyebrow: 'Cost guide',
      intro: 'Pressure-system prices vary because buyers often combine different services: mapping the system, preparing or reviewing a written scheme, opening and preparing plant, carrying out the statutory examination, undertaking specialist tests and repairing defects.',
      decision: { heading: 'Price the scheme and the examination as separate decisions', summary: 'A quote should say whether the provider will create or certify a scheme, which vessels, pipework and protective devices are included, what examination will be performed and what the dutyholder must do to prepare the system. Without that separation, two prices may describe materially different work.', checks: ['Count main plant, vessels and protective devices and identify system interconnections.', 'State whether a suitable current written scheme already exists.', 'Describe access, isolation, strip-down, shutdown and specialist-test requirements.'], action: 'Request a line-item quotation for inventory or discovery, written-scheme work, competent-person examination, reporting, travel and optional tests. Exclude servicing and repairs unless every bidder receives the same specification.' },
      sections: [
        { heading: 'What moves the figure', body: 'System complexity, number and type of examinable parts, missing records, new-scheme preparation, deterioration mechanisms, access, shutdown and non-destructive testing can all change the time and competence required.', points: ['Number of systems, vessels and devices', 'Simple, intermediate or complex system characteristics', 'Existing scheme quality and equipment history', 'Internal and external examination preparation', 'Specialist testing and multi-site scheduling'] },
        { heading: 'Why published prices need restraint', body: 'The public figures found by Vendor Atlas are mainly for simpler individual equipment such as dental pressure vessels and coffee boilers. They help constrain the bottom of the model but are not evidence of the price for a steam installation, industrial refrigeration plant or complex process system.', detail: 'The calculator states that limitation and uses a wider spread for pressure work. Actual quotes should rapidly replace the initial assumptions once comparable buyer data exists.' },
        { heading: 'Dutyholder preparation can be a separate cost', body: 'The competent person may require plant to be isolated, cooled, drained, opened, cleaned or stripped down. A maintenance contractor may undertake that work even when an independent inspection body performs the examination.', detail: 'Ask exactly who supplies labour, replacement seals, safety-valve work, access equipment and recommissioning. A low examination fee can omit substantial preparation.' },
      ], sources: [pssrBrief, pssrWse, pssrReg8, pssrReg9],
    },
    {
      path: '/pressure-systems/who-is-the-competent-person', title: 'Who is the competent person under PSSR?', description: 'How to select a pressure-system competent person with the right knowledge, experience, independence and authority.', cardPrompt: 'Match the inspection body and named engineer to system complexity.', eyebrow: 'Supplier guide',
      intro: 'Under PSSR, “competent person” describes a role and capability, not simply a job title. The organisation or individual needs sufficient knowledge, experience, facilities, independence and authority for the functions and complexity of the pressure system.',
      decision: { heading: 'Match competence to function and system category', summary: 'Drawing up or certifying a written scheme, examining a simple air receiver and taking responsibility for a complex steam or process installation are not interchangeable assignments. Ask the provider to state which competent-person functions it will perform and why its organisation is suitable.', checks: ['Identify who certifies the written scheme and who carries out each examination.', 'Request the applicable inspection-body accreditation scope or equivalent competence evidence.', 'Test independence from operating, maintenance and commercial pressures, plus authority to stop unsafe equipment.'], action: 'Do not appoint from a generic engineering-inspection claim alone. Give the provider sufficient system information, obtain a named proposal and verify that the organisation’s competence covers both the equipment complexity and required PSSR function.' },
      sections: [
        { heading: 'Organisation as well as individual', body: 'HSE guidance considers staffing, specialist services, organisation, experience, facilities and procedures. A competent person can be an in-house department, an individual or an external inspection organisation, depending on the system and safeguards.', detail: 'For larger or more complex systems, the provider may need access to specialist engineering disciplines and non-destructive testing while retaining responsibility for interpreting the results.' },
        { heading: 'UKAS accreditation', body: 'HSE notes that UKAS accreditation to the relevant inspection-body standard can help demonstrate appropriate competence. The buyer should still check the current schedule and whether it covers the pressure-equipment type and activity required.', detail: 'Vendor Atlas records provider claims but does not treat a logo or unsourced statement as proof of current accreditation scope.' },
        { heading: 'Independence and authority', body: 'The competent person needs independence from operating functions and enough authority to make objective safety decisions. An in-house arrangement can work, but organisational pressures and reporting lines need explicit safeguards.', points: ['Ability to stop use where necessary', 'Freedom from self-checking maintenance work', 'Access to plant history and specialists', 'Documented procedures and quality review'] },
      ], sources: [pssrUser, pssrBrief, pssrAcop],
    },
    {
      path: '/pressure-systems/pssr-vs-maintenance', title: 'PSSR examination vs maintenance: what is the difference?', description: 'Why a written scheme and statutory pressure-system examination do not replace servicing or safe operation.', cardPrompt: 'Identify the scheme, examination and maintenance evidence separately.', eyebrow: 'Comparison guide',
      intro: 'PSSR examination asks whether specified safety-critical parts are fit for continued use under the written scheme. Maintenance keeps the whole system operating safely. Both matter, and one contractor visit can contribute to both, but the legal documents should not be confused.',
      decision: { heading: 'Use the MOT and service distinction', summary: 'HSE compares examination under a written scheme to a vehicle MOT: it is a statutory judgement at defined intervals, not ongoing maintenance. A compressor service sheet or boiler maintenance record does not prove that a competent-person examination under a suitable written scheme has occurred.', checks: ['Can you produce the current written scheme identifying covered parts and intervals?', 'Can you produce a competent-person examination report matching that scheme?', 'Can you separately show routine maintenance, safe-limit checks and defect rectification?'], action: 'If any evidence stream is missing, commission the correct work explicitly. Do not ask a maintenance contractor to back-label a service as a PSSR examination or assume the inspection organisation will prepare plant without that being specified.' },
      sections: [
        { heading: 'Written scheme', body: 'The scheme defines the pressure-system parts, examination nature, preparation and maximum intervals. It must remain suitable and be reviewed as equipment ages, changes or reveals different deterioration.', detail: 'It is a controlled technical document, not a generic certificate attached to a service contract.' },
        { heading: 'Statutory examination', body: 'The competent person examines in accordance with the scheme, issues the required report, identifies repairs and handles findings of imminent danger. The work may be in-service, out-of-service or both.', detail: 'The examination report should be traceable to the scheme and actual equipment examined.' },
        { heading: 'Operation and maintenance', body: 'The user establishes safe operating limits, provides instructions and training, maintains the system and acts on defects. Maintenance frequency and content follow risk, manufacturer guidance, condition and operating experience—not simply the examination date.', detail: 'A good procurement pack assigns preparation, strip-down, reinstatement and repair responsibilities so that the system is safe before, during and after examination.' },
      ], sources: [pssrBrief, pssrUser, pssrReg9],
    },
  ],
  loler: [
    {
      path: '/loler', title: 'LOLER thorough examinations: a practical starting point', description: 'Understand when lifting equipment needs thorough examination, how intervals work and how to compare competent providers.', cardPrompt: 'Turn an equipment list into a defensible examination brief.', eyebrow: 'LOLER overview',
      intro: 'LOLER applies to lifting equipment used at work. The useful buying unit is an itemised asset register: what lifts, what it lifts, where it is installed, how it is used, which accessories connect the load and what the previous reports say.',
      decision: { heading: 'Start with the lifting function and asset', summary: 'The name on an invoice is not decisive. Ask whether work equipment raises or lowers people or loads and includes attachments used for anchoring, fixing or supporting it. Classify each main item and lifting accessory before assigning a six- or twelve-month planning interval.', checks: ['List fixed and mobile lifting equipment, attachments and every lifting accessory.', 'Record whether people are lifted, whether installation affects safety and whether exceptional events have occurred.', 'Find declarations, previous thorough-examination reports, defect actions and any examination scheme.'], action: 'Use the asset list to confirm scope and due dates with a competent person. Do not use a general annual service date for every item: people-lifting equipment and accessories normally follow a six-month maximum unless a competent-person scheme specifies otherwise.' },
      sections: [
        { heading: 'When examination is required', body: 'HSE identifies first use, installation or assembly where safety depends on it, regular in-service deterioration and exceptional circumstances such as damage, failure, major change or long disuse.', detail: 'A Declaration of Conformity can affect the first-use route for some new equipment, but does not remove the ongoing examination duty where deterioration can create danger.' },
        { heading: 'Intervals need item-level reasoning', body: 'Unless a competent-person examination scheme specifies different intervals, equipment and accessories lifting people and all lifting accessories normally have a six-month maximum; other lifting equipment normally has a twelve-month maximum.', points: ['People-lifting equipment: normally six months', 'Lifting accessories: normally six months', 'Other lifting equipment: normally twelve months', 'Exceptional events: examine when safety may have been jeopardised'] },
        { heading: 'Reports and defects matter more than stickers', body: 'The competent person must issue a written report containing specified information. Serious defects require immediate communication and can require a copy to the enforcing authority.', detail: 'A useful service manages item identity, findings, next due date and defect action without treating the presence of a certificate as proof that remedial work was completed.' },
      ], sources: [lolerDetail, lolerOverview, lolerIndg, lolerReg9],
    },
    {
      path: '/loler/does-loler-apply', title: 'Does LOLER apply to my equipment?', description: 'A decision aid for classifying lifting equipment, accessories, people-lifting use and examination triggers.', cardPrompt: 'Check function and use rather than relying on an equipment nickname.', eyebrow: 'Decision guide',
      intro: 'LOLER is likely to be relevant when work equipment is used for lifting or lowering people or loads. The boundary can be less obvious for attachments, excavators, pallet equipment, vehicle workshop equipment and lifting accessories, so borderline items need competent classification.',
      decision: { heading: 'Use an equipment–operation–trigger test', summary: 'Identify the item, confirm that its work function involves lifting or lowering, record whether it lifts people or loads, and then check first-use, installation, deterioration and exceptional-event triggers. PUWER can apply at the same time and is not an alternative label.', checks: ['Include slings, chains, shackles, beams and other accessories connecting equipment to a load.', 'Include attachments and plant used for lifting even if lifting is not the machine’s only function.', 'Record damage, overload, major repair, relocation, modification and long periods out of use.'], action: 'Create an asset register with use and last-report evidence, then ask a competent person to confirm LOLER scope and interval. Keep uncertain items visible rather than silently excluding them from the quote.' },
      sections: [
        { heading: 'Clear examples', body: 'Passenger and goods lifts, cranes, powered hoists, forklifts, vehicle lifts, MEWPs, patient hoists and lifting accessories are common groups. The precise examination still depends on design, use and environment.', points: ['Equipment lifting people', 'Equipment lifting goods or materials', 'Accessories attaching or supporting the load', 'Equipment whose safety depends on installation or assembly'] },
        { heading: 'Borderline examples', body: 'Some equipment moves or supports material without performing a lifting operation in the LOLER sense, while other plant becomes lifting equipment only in a particular configuration or use. HSE and industry guidance should be applied to the facts.', detail: 'The finder deliberately returns “may be relevant” for uncertain equipment. A convenient category answer is not worth hiding the need for equipment-specific judgement.' },
        { heading: 'LOLER and PUWER can both apply', body: 'LOLER deals specifically with lifting equipment and operations. PUWER covers work equipment more broadly, including suitability, maintenance and inspection. A thorough examination can be planned alongside PUWER inspection, but the reports should show which requirements were addressed.', detail: 'Ask providers whether their proposal covers LOLER only or a combined LOLER/PUWER scope, particularly for forklifts and materials-handling equipment.' },
      ], sources: [lolerOverview, lolerDetail, puwerInspection, lolerReg9],
    },
    {
      path: '/loler/cost', title: 'What does a LOLER thorough examination cost?', description: 'Understand item, accessory, visit and complexity costs when comparing lifting-equipment examination quotes.', cardPrompt: 'Use an itemised asset schedule instead of a vague site count.', eyebrow: 'Cost guide',
      intro: 'LOLER examination is commonly quoted by visit and item. Prices differ sharply between a sling, forklift, patient hoist, passenger lift and complex crane, so a total item count without equipment categories is not a comparable brief.',
      decision: { heading: 'Build the asset schedule before seeking a rate', summary: 'The cheapest credible quotation starts with each main item, accessory group, location, use and current report. Providers can then apply visit charges, per-item rates, volume discounts and specialist-equipment allowances to the same schedule.', checks: ['Separate main lifting machines from accessories and identify equipment lifting people.', 'State makes, models, capacities, serial numbers and locations where known.', 'Identify access, isolation, load-test, specialist-test, defect and out-of-hours requirements.'], action: 'Request the visit minimum, rate by equipment category, accessory rate, reporting, travel and exclusions as separate lines. Ask how unidentified assets and failed-item re-examinations will be priced.' },
      sections: [
        { heading: 'What moves the price', body: 'Main equipment complexity, number of safety-critical parts, installation, access, item identification, volume, site geography and the need for supplementary tests all affect examination time.', points: ['Minimum site attendance', 'Main equipment by category', 'Accessories by count or kit', 'People-lifting and specialist-equipment complexity', 'Travel, access and multi-site coordination'] },
        { heading: 'How the Vendor Atlas model works', body: 'The calculator uses a visit amount, per-main-item amount, per-accessory amount, people-lifting and complex-equipment allowances and additional-site attendance. Every factor is displayed.', detail: 'Provider-published examples show that some providers use per-item prices while specialist arborist services use kit pricing. The initial model is deliberately broad and must be refined with comparable real quotes.' },
        { heading: 'Do not hide remedial work in the examination fee', body: 'Maintenance, repair, replacement parts, load testing and re-examination after defects can be separately chargeable. Comparing a pure examination with a service-and-repair package produces a misleading headline difference.', detail: 'Ask who owns each defect action and whether a repair provider will be independent of the final continued-use judgement.' },
      ], sources: [lolerDetail, lolerIndg, lolerReg10],
    },
    {
      path: '/loler/who-can-carry-out-a-loler-examination', title: 'Who can carry out a LOLER thorough examination?', description: 'How to test a competent person’s equipment knowledge, practical experience, independence and reporting method.', cardPrompt: 'Match the examiner to the actual equipment, not just the abbreviation.', eyebrow: 'Supplier guide',
      intro: 'A competent person must have enough practical and theoretical knowledge and experience of the particular lifting equipment to detect defects or weaknesses and assess their importance for continued safe use.',
      decision: { heading: 'Competence is equipment-specific', summary: 'Experience examining loose lifting accessories does not automatically establish competence for a passenger lift, crane, MEWP or patient hoist. Ask the provider to connect the named examiner’s knowledge and experience to each equipment category in your schedule.', checks: ['Request the proposed examiner’s equipment-specific qualifications, experience and technical support.', 'Confirm sufficient independence from maintenance work and commercial pressure.', 'Review a redacted Schedule 1 report and the process for immediate and enforcing-authority defect reporting.'], action: 'Appoint only after the provider has accepted the complete asset scope and shown a method for each category. Verify insurance and any claimed accreditation or membership from current evidence rather than relying on a directory badge.' },
      sections: [
        { heading: 'Practical and theoretical knowledge', body: 'The examiner needs to understand design, use, deterioration, discard criteria and safety-critical components well enough to judge defects. Competence can come from different qualifications and experience routes.', detail: 'The dutyholder should ask how competence is selected, authorised and maintained for each equipment family, especially within national inspection organisations.' },
        { heading: 'Independence', body: 'HSE says the competent person should be sufficiently independent and impartial to make objective decisions. The same organisation can sometimes service and examine equipment, but the individual examiner should not simply assess their own maintenance work.', detail: 'Ask how conflicts are managed, who can stop equipment and how repair recommendations are separated from the statutory conclusion.' },
        { heading: 'Reporting capability', body: 'The examination is incomplete without the required report. Test whether the provider records item identity, examination date, next due date, defects, danger classification and necessary action and can transmit serious findings promptly.', points: ['Immediate verbal escalation', 'Schedule 1 written report', 'Enforcing-authority copies where required', 'Traceable next date and defect closure'] },
      ], sources: [lolerDetail, lolerFaq, lolerIndg, lolerReg10],
    },
    {
      path: '/loler/loler-vs-puwer', title: 'LOLER vs PUWER: which examination or inspection applies?', description: 'Understand how lifting-equipment thorough examination and broader work-equipment inspection overlap without becoming interchangeable.', cardPrompt: 'Define whether the quote covers LOLER, PUWER or both.', eyebrow: 'Comparison guide',
      intro: 'LOLER adds lifting-specific duties to the broader PUWER framework. Lifting equipment can therefore need a LOLER thorough examination and separate or coordinated PUWER inspection, maintenance and safe-use controls.',
      decision: { heading: 'Do not choose one acronym and discard the other', summary: 'LOLER focuses on lifting equipment, lifting operations and specified thorough examination. PUWER applies to work equipment more generally and requires suitability, maintenance and inspection where safety depends on installation or deterioration. The same asset can sit under both.', checks: ['Does the equipment raise or lower people or loads, bringing the lifting-specific regime into view?', 'Which risks concern lifting components and which concern the wider machine, controls, guarding or work environment?', 'Does the supplier report explicitly state which LOLER and PUWER matters were examined?'], action: 'Ask for a scope matrix showing asset categories, LOLER examination, PUWER inspection, maintenance and any excluded specialist tests. Do not accept a combined certificate unless the evidence demonstrates both required scopes.' },
      sections: [
        { heading: 'LOLER thorough examination', body: 'The competent person systematically examines lifting equipment and safety-critical parts at statutory points and intervals, reports defects and sets the next date or follows a competent-person scheme.', detail: 'The judgement is lifting-equipment specific and the report must contain the information required by the Regulations.' },
        { heading: 'PUWER inspection', body: 'PUWER inspection is risk based. It is required where safety depends on installation conditions, where deterioration can cause danger and after exceptional circumstances. The content and frequency should be determined from risk and manufacturer information.', detail: 'Routine operator checks and maintenance can sit alongside more formal inspections, but records should show who did what and why.' },
        { heading: 'Buying a combined service', body: 'A combined visit may reduce disruption and cost, particularly for materials-handling equipment. The quotation should identify the competent people, standards, checks and report fields used for each regime rather than hiding both behind “compliance inspection”.', detail: 'A clear scope lets buyers compare providers and prevents one bidder from appearing cheaper because it has omitted the broader machine inspection.' },
      ], sources: [lolerOverview, lolerDetail, puwerInspection, lolerFaq],
    },
  ],
  asbestos: [
    {
      path: '/asbestos', title: 'Asbestos surveys and registers: a practical starting point', description: 'Check the duty to manage, choose the right asbestos survey and prepare a comparable provider brief.', cardPrompt: 'Move from an uncertain building record to the right survey and usable register.', eyebrow: 'Asbestos overview',
      intro: 'Asbestos procurement starts with the building, the person responsible for maintenance and the work that will happen there. The survey is evidence for a management decision; it is not a generic certificate that makes every future job safe.',
      decision: { heading: 'Define the premises and decision first', summary: 'For normal occupation of relevant non-domestic premises, a management survey may be needed to support the duty to manage. Before refurbishment or demolition disturbs the fabric, the affected area needs a more intrusive survey designed for that work.', checks: ['Identify the dutyholder and every building or common area in scope.', 'Find construction dates, drawings, old surveys, registers and records of previous removal.', 'Describe planned maintenance, refurbishment or demolition by area and depth.'], action: 'If records cannot reliably show that the work area is free of asbestos, commission competent scoping before disturbance. Give each bidder the same premises list, work plan, access constraints and required deliverables.' },
      sections: [
        { heading: 'The duty is ongoing', body: 'The duty to manage is not completed by buying one survey. Information must be assessed, recorded, communicated to people who may disturb materials and kept current as condition or premises change.', detail: 'HSE says the register should be easy to find, kept up to date and checked before work begins. A management plan should assign actions and review them.' },
        { heading: 'Survey type follows the use', body: 'A management survey supports normal occupation and foreseeable maintenance. A refurbishment and demolition survey is intrusive and targets the fabric that planned work will disturb.', points: ['Management survey for occupation and routine maintenance', 'Refurbishment survey for the defined alteration area', 'Demolition survey for the whole structure being demolished', 'Reinspection to review known materials and condition'] },
        { heading: 'The deliverable must be usable', body: 'A useful report identifies inspected areas, inaccessible areas, samples, presumed or identified materials, condition, extent and recommended action. It should feed the register or the project work controls.', detail: 'Ambiguous room names, unmarked plans and hidden exclusions can make a technically completed survey unsafe to use. Specify naming, drawings, photographs and data format before appointment.' },
      ], sources: [asbestosDuty, asbestosSurvey, asbestosRegister, asbestosReg4],
    },
    {
      path: '/asbestos/do-i-need-an-asbestos-survey', title: 'Do I need an asbestos survey?', description: 'A decision aid for non-domestic premises, common areas, maintenance, refurbishment and demolition.', cardPrompt: 'Check whether the duty or planned work creates a survey need.', eyebrow: 'Decision guide',
      intro: 'A survey is likely to be relevant where a dutyholder cannot otherwise determine whether asbestos is present, or where work could disturb hidden material. The survey type and area must match the decision being made.',
      decision: { heading: 'Use two separate questions', summary: 'First ask whether you control maintenance of non-domestic premises or common parts. Then ask whether planned work will disturb the building fabric. The first points towards management information; the second can require an intrusive refurbishment or demolition survey.', checks: ['Was any relevant structure built or refurbished before 2000?', 'Is there a complete, current register that covers every area people may disturb?', 'Will maintenance, installation, refurbishment or demolition penetrate fabric?'], action: 'Treat unknown age, inaccessible areas and incomplete records as scoping gaps, not proof of absence. Stop planned disturbance until the relevant area has suitable information and controls.' },
      sections: [
        { heading: 'Strong management-survey signals', body: 'The premises are non-domestic, were built before 2000, have no dependable register, contain suspect material or have known asbestos that needs condition monitoring.', detail: 'Common parts of domestic premises can also fall within the duty. Domestic rooms themselves are treated differently, so mixed-use property boundaries need care.' },
        { heading: 'Strong intrusive-survey signals', body: 'Refurbishment, services installation, major maintenance or demolition will open walls, ceilings, floors, ducts, risers or other concealed fabric.', points: ['Define the exact work area', 'Describe the depth of intrusion', 'Arrange safe access and isolation', 'Agree making-good responsibilities'] },
        { heading: 'When a new survey may not be needed', body: 'Reliable records may already identify the material and fully cover the work area, or dependable construction evidence may show the relevant fabric dates from after 2000. Those conclusions must be checked against the actual scope.', detail: 'A recent-looking report is not enough if it excludes the area, was not intrusive to the required depth or no longer reflects the building.' },
      ], sources: [asbestosDuty, asbestosSurvey, asbestosReg4, asbestosHsg264],
    },
    {
      path: '/asbestos/cost', title: 'What does a commercial asbestos survey cost?', description: 'Understand how survey type, floor area, samples, access and reporting affect a commercial asbestos-survey quote.', cardPrompt: 'Create a comparable scope instead of relying on a headline starting price.', eyebrow: 'Cost guide',
      intro: 'Commercial asbestos-survey prices depend on survey type, building size and complexity, access, number of suspect materials, laboratory samples and the report or register format required. A cheap quote with broad exclusions may not support the intended decision.',
      decision: { heading: 'Price the scope, not the address', summary: 'Give providers the same building schedule, floor plans, work areas, survey type, access conditions and output requirements. Ask whether samples, laboratory analysis, travel, out-of-hours work, intrusive opening and reinstatement are included.', checks: ['State gross area, floors, blocks, plant spaces and occupied restrictions.', 'Define management, refurbishment, demolition or reinspection work by area.', 'Request a sample allowance and a stated rate for additional samples.'], action: 'Compare a fixed base scope plus explicit variable rates. Keep removal, remediation and project management separate unless every provider has priced the same additional work.' },
      sections: [
        { heading: 'What moves the price', body: 'More rooms and construction types increase inspection time. Intrusive work requires planning and safe access. Samples add traceability and laboratory work. Poor records and occupied areas can slow the survey.', points: ['Survey type and defined work area', 'Building size, age and complexity', 'Access, isolation and making good', 'Expected and additional samples', 'Plans, register data and turnaround'] },
        { heading: 'How the Vendor Atlas range works', body: 'The calculator adds transparent allowances for attendance, each building or block, expected sample locations, intrusive survey work, complex premises and extra sites, then applies a visible range around the total.', detail: 'The starting values are calibrated from a small set of provider-published examples. They are planning guidance, not a national average or supplier quotation.' },
        { heading: 'Do not compare unlike deliverables', body: 'One quote may include marked plans, priority assessment, register data and extra samples while another covers only a visual visit and PDF. Require the same deliverable list and exclusions.', detail: 'If a survey supports planned work, specify the work boundary and how inaccessible areas will be resolved before contractors begin.' },
      ], sources: [asbestosSurvey, asbestosHsg264, asbestosRegister],
    },
    {
      path: '/asbestos/who-can-carry-out-an-asbestos-survey', title: 'Who can carry out an asbestos survey?', description: 'How to check surveyor competence, accreditation scope, independence, insurance and report quality.', cardPrompt: 'Verify the organisation, named surveyor and method before appointment.', eyebrow: 'Supplier guide',
      intro: 'The client must appoint someone competent for the survey type and premises. HSE strongly recommends using an organisation accredited for asbestos surveying and points buyers to the UKAS directory, but the current scope and proposed people still need checking.',
      decision: { heading: 'Verify three layers of evidence', summary: 'Check the organisation and its current accreditation scope, the named surveyor’s training and comparable experience, and the method and report that will be used on your premises. A logo or provider claim alone is not the full appointment check.', checks: ['Check the current UKAS directory entry and scope for the required survey type.', 'Ask who will attend and what comparable buildings and projects they have surveyed.', 'Review a redacted report for plans, photographs, exclusions, sampling and assessments.'], action: 'Record evidence at the date of appointment and verify insurance, impartiality, capacity, laboratory arrangements and complaint process directly. Vendor Atlas records public evidence but does not approve providers.' },
      sections: [
        { heading: 'Organisation evidence', body: 'UKAS accreditation for inspection bodies is a strong, independently assessed signal when its current schedule covers the work being bought. Check the official directory rather than relying only on a website badge.', detail: 'Accredited scope can differ between organisations and can change. Record the directory result with the quotation and contract.' },
        { heading: 'Named-person competence', body: 'Training such as BOHS survey qualifications can support competence, but relevant practical experience, quality supervision and the ability to understand the project remain necessary.', points: ['Named lead surveyor', 'Comparable premises experience', 'Intrusive-survey planning experience', 'Current training and authorisation', 'Quality review and escalation'] },
        { heading: 'Method and independence', body: 'The survey plan should resolve access, exclusions, sampling, laboratory analysis, reporting and urgent findings. Where the same provider offers removal, ask how impartial survey judgements and later commercial recommendations are separated.', detail: 'The appointment should make responsibility for damage, reinstatement, occupancy controls and unexpected materials explicit.' },
      ], sources: [asbestosSurvey, asbestosHsg264, asbestosDuty],
    },
    {
      path: '/asbestos/management-vs-refurbishment-survey', title: 'Management survey vs refurbishment and demolition survey', description: 'Choose the asbestos survey that matches normal occupation, intrusive refurbishment or demolition.', cardPrompt: 'Avoid using a non-intrusive survey to release intrusive work.', eyebrow: 'Comparison guide',
      intro: 'Management surveys and refurbishment or demolition surveys are not quality tiers. They answer different questions. A sound procurement brief identifies the use, area and degree of intrusion before naming the survey.',
      decision: { heading: 'Match investigation depth to disturbance', summary: 'A management survey finds materials that could be disturbed during normal occupation and foreseeable maintenance. A refurbishment or demolition survey locates materials within the fabric that the defined project will disturb and is normally more destructive.', checks: ['Is the building remaining occupied for normal use?', 'Which exact areas and elements will the project disturb?', 'Can those areas be safely vacated, isolated and opened for inspection?'], action: 'Do not release intrusive work from a management survey unless competent review confirms it fully covers the actual disturbance. Commission project-specific investigation for excluded or concealed areas.' },
      sections: [
        { heading: 'Management survey', body: 'The survey supports the live asbestos register and management plan. It is generally less intrusive but must still cover accessible materials that could be disturbed during normal use and maintenance.', detail: 'Its value depends on clear plans, condition records, assumptions and exclusions, plus an operating process that checks the register before work.' },
        { heading: 'Refurbishment and demolition survey', body: 'This survey is designed around a defined project and investigates concealed fabric in the work area. The space normally needs to be vacant and controlled because inspection may be destructive.', points: ['Give the surveyor drawings and scope', 'Permit sufficient intrusive access', 'Resolve services, occupancy and making good', 'Communicate results into the construction plan'] },
        { heading: 'Common procurement failure', body: 'A buyer asks for an “asbestos survey” without describing the planned work, receives a management survey and later discovers that the report cannot clear concealed areas for refurbishment.', detail: 'Make the intended decision part of the quote request, and require exclusions and inaccessible areas to be prominent rather than buried in standard text.' },
      ], sources: [asbestosSurvey, asbestosHsg264, asbestosRegister],
    },
  ],
  'fire-risk-assessment': [
    {
      path: '/fire-risk-assessment', title: 'Fire risk assessments for business premises', description: 'Check the responsible-person duty, assessment scope, cost inputs and provider evidence for premises in England and Wales.', cardPrompt: 'Turn the premises and occupancy facts into a usable assessment brief.', eyebrow: 'Fire risk overview',
      intro: 'A fire risk assessment records how the responsible person has identified fire hazards, people at risk and the precautions needed for the premises. The document must reflect the building, use, occupiers and management arrangements rather than a generic checklist.',
      decision: { heading: 'Start with responsibility and premises use', summary: 'Employers, owners, landlords, occupiers and others controlling non-domestic premises can be responsible persons. Paying guest accommodation and common parts of blocks of flats are also covered. Several people may share duties and must co-operate.', checks: ['Name every responsible person and the parts of the premises each controls.', 'Describe occupancy, sleeping use, vulnerable people, processes and fire hazards.', 'Find the current assessment, plans, fire-system records and unresolved actions.'], action: 'If the premises is in scope and no suitable current assessment is available, record the gap and arrange a competent assessment. Give each provider the same building, occupancy, records and access information.' },
      sections: [
        { heading: 'Five assessment steps', body: 'The Home Office sequence is to identify hazards, identify people at risk, evaluate and reduce risk, record findings and plans, then review and update the assessment.', detail: 'The assessment should connect each significant finding to a control or action. An equipment list alone does not evaluate escape, management, training or the needs of people present.' },
        { heading: 'Responsibility remains with the dutyholder', body: 'A responsible person can assess simple premises if competent or appoint a professional assessor. Paying for an assessor does not transfer responsibility for the suitability of the assessment or completion of actions.', points: ['Confirm the premises boundary', 'Share information between dutyholders', 'Select help suited to the premises', 'Track actions and review triggers'] },
        { heading: 'Assessment and remedial work are separate', body: 'The assessment identifies and evaluates risk. Alarm servicing, emergency-lighting tests, fire-door repair, compartmentation work and training may follow, but each needs its own scope and evidence.', detail: 'Keep the assessment conclusion, action priorities and any later product sales visible so competing quotations can be compared.' },
      ], sources: [fireResponsibilities, fireAssessment, fireChecklist, fireArticle9],
    },
    {
      path: '/fire-risk-assessment/do-i-need-a-fire-risk-assessment', title: 'Do I need a fire risk assessment?', description: 'A decision aid for workplaces, public premises, paying guests, shared buildings and common parts in England and Wales.', cardPrompt: 'Check responsibility, premises scope and review triggers.', eyebrow: 'Decision guide',
      intro: 'In England and Wales, a responsible person must carry out and regularly review a fire risk assessment for covered premises. The key questions are who controls the premises, who may be at risk and whether the existing assessment still matches current conditions.',
      decision: { heading: 'Apply the responsible-person test', summary: 'You are likely to hold duties if you are an employer, owner, landlord, occupier, managing agent or another person controlling non-domestic premises. A building can have several responsible persons with different areas and systems.', checks: ['Are people employed at or admitted to the premises?', 'Do you control maintenance, occupation, shared areas or paying guest accommodation?', 'Has use, layout, occupancy, fire precautions or risk changed since the last assessment?'], action: 'Document the people and areas under each party’s control. If responsibility or assessment validity is uncertain, obtain competent advice rather than leaving a gap between landlord, tenant and managing agent.' },
      sections: [
        { heading: 'Premises normally covered', body: 'Workplaces, offices, shops, factories, warehouses, hospitality venues, care and education premises, paying guest accommodation and the common parts of blocks of flats fall within the fire-safety regime.', detail: 'A single private domestic dwelling is treated differently, but business use, paying guests and common areas change the position.' },
        { heading: 'Review triggers', body: 'Article 9 requires review when there is reason to suspect the assessment is no longer valid or after a significant change. The Home Office checklist also points to fires, near misses, building alterations, changed stock and dangerous substances.', points: ['New layout or extension', 'Changed use or occupancy', 'Fire or near miss', 'New process or dangerous substance', 'Changed escape or alarm arrangements'] },
        { heading: 'Simple and complex premises', body: 'A competent responsible person can assess the simplest premises using the official guides. Sleeping accommodation, vulnerable occupants, complex buildings, industrial hazards and shared responsibility demand deeper knowledge.', detail: 'The question is not whether an external assessor is always mandatory. It is whether the people doing the work can produce a suitable and sufficient assessment for this premises.' },
      ], sources: [fireResponsibilities, fireAssessment, fireArticle9, fireGuides],
    },
    {
      path: '/fire-risk-assessment/cost', title: 'What does a commercial fire risk assessment cost?', description: 'Understand how premises size, floors, occupancies, sleeping risk and assessment complexity affect provider quotations.', cardPrompt: 'Compare the same premises scope, report and exclusions.', eyebrow: 'Cost guide',
      intro: 'Commercial fire risk assessment prices are shaped by the premises, not employee count alone. Floor area, storeys, separate occupancies, sleeping or vulnerable people, industrial hazards, records, access and reporting all affect the work.',
      decision: { heading: 'Ask providers to price the same premises', summary: 'A comparable quotation identifies every building, floor, occupancy, shared area and higher-risk use. It states the site visit, records review, written report, action plan, travel, VAT and any specialist work that is excluded.', checks: ['Provide floor area, storeys, use, occupancy and normal operating hours.', 'Identify sleeping risk, vulnerable people, dangerous substances and shared responsibility.', 'List available plans, previous assessments, system records and open actions.'], action: 'Request one fixed scope plus separate rates for extra buildings, visits or specialist input. Do not compare a short visual inspection with a full assessment and prioritised action plan as if they were the same service.' },
      sections: [
        { heading: 'Price inputs', body: 'More floors, rooms and occupiers take longer to inspect and document. Sleeping risk, vulnerable occupants, industrial processes, complex escape, shared systems and missing records increase judgement and reporting effort.', points: ['Premises size and storeys', 'Separate occupancies', 'People and evacuation needs', 'Hazards and fire precautions', 'Records and report requirements'] },
        { heading: 'Vendor Atlas calculation', body: 'The calculator displays allowances for assessment setup, each floor, each separate occupancy, sleeping or vulnerable occupants, complex premises and additional sites. It widens the total into a planning range.', detail: 'The settings use three provider-published price schedules. They are not a national average and they do not set a fee for unusual or specialist buildings.' },
        { heading: 'Quotation exclusions', body: 'External-wall appraisal, intrusive compartmentation surveys, fire engineering, evacuation modelling, alarm design, equipment servicing and remedial work can sit outside a standard assessment.', detail: 'Require exclusions in the quotation and final report. If further specialist work is needed, the assessment should state the question and responsible action rather than imply it was completed.' },
      ], sources: [fireAssessment, fireChecklist, fireGuides],
    },
    {
      path: '/fire-risk-assessment/who-can-carry-out-a-fire-risk-assessment', title: 'Who can carry out a fire risk assessment?', description: 'How to check assessor competence, premises experience, independent registration, insurance and report quality.', cardPrompt: 'Test the named assessor against the building and risks.', eyebrow: 'Supplier guide',
      intro: 'The responsible person may carry out a straightforward assessment if competent. When external help is needed, the appointment should test the named assessor’s knowledge, experience and ability against the premises rather than relying on a company claim.',
      decision: { heading: 'Match competence to premises complexity', summary: 'A small office, sleeping-risk building, care setting, industrial process and high-rise residential building require different experience. Government guidance tells responsible persons to keep records of the steps taken when selecting an assessor.', checks: ['Ask for the named assessor, current registration or certification and relevant experience.', 'Request a redacted report for a comparable premises type and complexity.', 'Verify professional indemnity, public liability, quality review and complaint arrangements.'], action: 'Keep the selection evidence with the fire-safety records. Verify register or certification claims with the issuing body and confirm who takes responsibility for specialist matters outside the assessor’s competence.' },
      sections: [
        { heading: 'Competence evidence', body: 'Relevant training, practical experience, continuing development, third-party registration or company certification and access to technical support can support the appointment.', detail: 'No single badge proves competence for every building. Check the current entry, scope and named person against the work being commissioned.' },
        { heading: 'Comparable report', body: 'A sample report should show the premises boundary, people at risk, hazards, evaluation of precautions, significant findings, priorities, actions, limitations and review information.', points: ['Premises-specific findings', 'Evidence behind conclusions', 'Prioritised action plan', 'Visible limitations', 'Review and record requirements'] },
        { heading: 'Commercial independence', body: 'Some assessors also sell alarms, doors, extinguishers, servicing or remedial work. That can be practical, but the assessment evidence and priority should not depend on buying the same provider’s products.', detail: 'Ask how recommendations are quality checked and obtain comparable remedial quotations where cost or design is material.' },
      ], sources: [fireAssessment, fireArticle18, fireResponsibilities],
    },
    {
      path: '/fire-risk-assessment/review-or-new-assessment', title: 'Fire risk assessment review or new assessment?', description: 'Decide whether to review an existing record or commission a fresh premises assessment after changes or missing evidence.', cardPrompt: 'Define what changed and what evidence remains valid.', eyebrow: 'Comparison guide',
      intro: 'A review checks whether the existing fire risk assessment remains valid and updates it where needed. A fresh assessment is more suitable when the premises, responsibility, evidence or original assessment cannot support a dependable update.',
      decision: { heading: 'Test the existing record against current conditions', summary: 'Check that the assessment identifies the correct responsible people, premises, occupancy, hazards, escape arrangements, fire precautions and actions. A date alone does not show that the record still represents the building.', checks: ['Can every significant finding be traced to the current premises?', 'Have layout, use, occupants, processes or fire-safety systems changed?', 'Are original limitations, missing areas and overdue actions resolved?'], action: 'Give providers the existing assessment and a change schedule. Ask them to state whether the quotation is for a documented review, an updated assessment or a fresh assessment and what evidence will be rechecked.' },
      sections: [
        { heading: 'Review route', body: 'A review suits a usable assessment where the premises remains substantially represented and the reviewer can verify changes, actions, fire precautions and current management arrangements.', detail: 'The review should be recorded with its date, findings, changes and resulting actions. A signature added without checking the premises and evidence is not a meaningful review.' },
        { heading: 'Fresh assessment route', body: 'A new assessment is appropriate when no written record exists, the scope is unclear, major changes have occurred or the previous work lacks the information needed to judge risk.', points: ['New or acquired premises', 'Changed use or major refurbishment', 'Missing or generic report', 'Unresolved premises boundary', 'Fire or material near miss'] },
        { heading: 'No universal annual expiry', body: 'The Fire Safety Order requires regular review and specific review when validity is doubtful or significant change occurs. The legislation does not set one universal annual expiry date for every premises.', detail: 'Contracts, insurers, housing policies or sector guidance may set additional review frequencies. Record their source separately from the statutory trigger.' },
      ], sources: [fireArticle9, fireAssessment, fireChecklist],
    },
  ],
  legionella: [
    {
      path: '/legionella', title: 'Legionella risk assessment and water-system control', description: 'Check dutyholder signals, water-system scope, assessment costs and provider evidence under HSE ACOP L8.', cardPrompt: 'Turn outlets, assets and exposed people into an assessment brief.', eyebrow: 'Legionella overview',
      intro: 'Legionella risk assessment starts with the water system and the people who can be exposed to water droplets. The dutyholder needs an assessment that identifies risk sources and leads to a workable control scheme, not a certificate detached from the premises.',
      decision: { heading: 'Map the system before buying tests', summary: 'Employers and people controlling premises should identify water systems where legionella can grow and spread, appoint competent help where needed and assess the risk. Hot and cold systems, cooling plant, spa pools and other aerosol-producing systems need different technical knowledge.', checks: ['Count outlets, tanks, calorifiers, cooling or process plant and separate buildings.', 'Identify stored water, recirculation, low use, temperature problems and aerosol routes.', 'Record who is exposed, including people with increased susceptibility.'], action: 'If the water-system boundary or current assessment is uncertain, commission a scoped assessment before buying a routine sampling package. Give each provider the same asset counts, plans, records and access conditions.' },
      sections: [
        { heading: 'Assessment output', body: 'A suitable assessment identifies the system, foreseeable exposure, conditions supporting bacterial growth and the controls needed. It should explain responsibilities and actions in terms the responsible person can operate.', detail: 'The report should include or reference a schematic, asset inventory, risk findings, control measures, monitoring requirements, corrective actions and review triggers.' },
        { heading: 'Written control scheme', body: 'Where the assessment identifies risk, ACOP L8 expects a written scheme describing the system and the measures used to control it. Named people need authority, competence and access to records.', points: ['System description and schematic', 'Operating and monitoring limits', 'Inspection, cleaning and maintenance tasks', 'Corrective actions and escalation', 'Record retention and review'] },
        { heading: 'Sampling has a defined purpose', body: 'Routine bacterial sampling is not the starting point for every water system. HSE guidance links sampling to system type, control performance and specific circumstances.', detail: 'A quotation should separate assessment, temperature monitoring, microbiological sampling, laboratory fees and remedial work so the buyer can see what evidence each item provides.' },
      ], sources: [legionellaL8, legionellaHsg274, legionellaEmployer, legionellaControl],
    },
    {
      path: '/legionella/do-i-need-a-legionella-risk-assessment', title: 'Do I need a legionella risk assessment?', description: 'A decision aid for employers, landlords and people controlling hot, cold, cooling and other water systems.', cardPrompt: 'Check control, exposure and water-system risk signals.', eyebrow: 'Decision guide',
      intro: 'Health and safety law requires dutyholders to assess foreseeable exposure to legionella and control the risk. The assessment can be simple for a low-risk system, but the duty does not disappear because no certificate or fixed testing interval is specified.',
      decision: { heading: 'Use the water and exposure test', summary: 'A legionella assessment is relevant when an undertaking or premises includes a water system that can support bacterial growth and release droplets people can inhale. Stored or recirculating water, showers, low-use outlets, cooling towers and susceptible users strengthen the need for specialist input.', checks: ['Do you employ people, control premises or manage rented accommodation with a water system?', 'Can water be stored, recirculated, stagnate or sit within temperatures that permit growth?', 'Can the system release spray or droplets to employees, tenants, visitors or the public?'], action: 'Document the water-system boundary and responsible people even where the initial conclusion is low risk. If the system is complex or the controls are uncertain, appoint someone with relevant water-system competence.' },
      sections: [
        { heading: 'Commercial and public premises', body: 'Offices, factories, shops, schools, hotels, care settings, leisure facilities and public buildings contain hot and cold systems of different complexity. The assessment must reflect their assets and users.', detail: 'A small mains-fed system can justify simple controls. Stored water, many outlets, mixed temperatures and vulnerable people require a more detailed assessment.' },
        { heading: 'Landlord duties', body: 'HSE states that landlords have duties to assess and control legionella risk. It also explains that most rented domestic hot and cold systems are low risk and do not require elaborate testing arrangements.', points: ['Identify foreseeable risk', 'Remove redundant pipework where practical', 'Maintain temperature and turnover controls', 'Inform tenants about control measures'] },
        { heading: 'Assessment review', body: 'Review the assessment when there is reason to think it is no longer valid. Changes to the system, use, occupancy, responsible people or control performance can trigger review.', detail: 'ACOP L8 does not create one universal two-year certificate expiry for every system. The review timing should follow the assessment, system changes and evidence that controls remain effective.' },
      ], sources: [legionellaEmployer, legionellaLandlords, legionellaL8, coshhReg6],
    },
    {
      path: '/legionella/cost', title: 'What does a legionella risk assessment cost?', description: 'Understand how outlets, tanks, stored water, system complexity, susceptible users and site count affect quotations.', cardPrompt: 'Use an outlet and asset schedule to compare assessment prices.', eyebrow: 'Cost guide',
      intro: 'Commercial legionella risk assessment prices depend on water-system scale and complexity. The number of outlets, tanks, calorifiers, buildings and specialist systems is more useful than floor area alone when providers estimate attendance and reporting effort.',
      decision: { heading: 'Count outlets and main assets', summary: 'A comparable quotation states how many taps, showers and other outlets are included, which tanks, calorifiers and circulation loops will be inspected, and whether a schematic, asset register, control scheme, sampling or return visit is included.', checks: ['Count outlets by building and identify little-used or aerosol-producing points.', 'List tanks, calorifiers, cooling plant, spa or process systems and circulation loops.', 'State available schematics, assessments, monitoring data, sampling results and open actions.'], action: 'Ask providers to separate the core assessment from sampling, laboratory fees, monitoring visits, cleaning, remedial plumbing and training. Compare the same report and control-scheme deliverables before comparing the total.' },
      sections: [
        { heading: 'Price inputs', body: 'Outlet count drives inspection and recording time. Stored water, recirculation, cooling or spa systems, multiple plant rooms, poor records and susceptible users add technical and reporting work.', points: ['Water outlets and buildings', 'Tanks, calorifiers and loops', 'Higher-risk specialist systems', 'People and exposure routes', 'Schematics, records and report format'] },
        { heading: 'Vendor Atlas calculation', body: 'The calculator displays allowances for assessment setup, each water outlet, each tank or main asset, higher-risk systems or susceptible people, complex systems and additional sites.', detail: 'The initial settings use price information published by Birmingham Water Solutions, Aqua Legion UK and uRisk. They are planning values, not a national tariff or provider quotation.' },
        { heading: 'Separate assessment from testing', body: 'Sampling can answer a defined control or investigation question, but a negative result does not replace a suitable assessment and control scheme. Laboratory work should be priced separately.', detail: 'The quote should state sample count, accredited laboratory, analysis method, interpretation, repeat conditions and any transport or express charges when sampling is included.' },
      ], sources: [legionellaL8, legionellaHsg274, legionellaControl],
    },
    {
      path: '/legionella/who-can-carry-out-a-legionella-risk-assessment', title: 'Who can carry out a legionella risk assessment?', description: 'How to check water-system competence, independence, method, insurance and report quality before appointment.', cardPrompt: 'Match the named assessor to the water system and people at risk.', eyebrow: 'Supplier guide',
      intro: 'The dutyholder must appoint competent help where internal knowledge is insufficient. Competence depends on the water-system type, risk, practical assessment skill and ability to specify workable controls rather than one protected job title.',
      decision: { heading: 'Test system-specific competence', summary: 'A person assessing a simple mains-fed office does not need the same experience as someone assessing cooling towers, healthcare water systems or spa pools. Ask the provider to connect the named assessor’s training and work history to every system in the brief.', checks: ['Request the named assessor’s training, experience and authorisation for the system type.', 'Review a redacted report with a schematic, asset list, findings and control scheme.', 'Check insurance, quality review, conflicts and laboratory arrangements where sampling is offered.'], action: 'Record provider evidence at appointment and verify any trade-association, certification or laboratory claims with the issuing body. Vendor Atlas reports source evidence but does not certify competence.' },
      sections: [
        { heading: 'Named-person evidence', body: 'The provider should identify who will attend, who will review the report and what comparable systems they have assessed. Training alone does not show current practical experience with the premises type.', detail: 'Ask how competence is checked and maintained, who handles technical escalation and which tasks will be subcontracted.' },
        { heading: 'Assessment method', body: 'The proposal should cover system mapping, asset inspection, operating evidence, exposure routes, susceptible people, existing controls, risk evaluation and a usable written control scheme.', points: ['Scope and system boundary', 'Schematic and asset register', 'Control evidence and measurements', 'Prioritised findings', 'Review and corrective-action process'] },
        { heading: 'Commercial separation', body: 'Many providers also sell monitoring, sampling, cleaning, dosing and remedial plumbing. Keep the assessment findings and resulting service proposal as separate lines.', detail: 'Where the assessor recommends continuing work from the same provider, ask for the evidence, task frequency, acceptance limits and corrective-action rule behind each item.' },
      ], sources: [legionellaL8, legionellaEmployer, legionellaControl],
    },
    {
      path: '/legionella/risk-assessment-vs-water-testing', title: 'Legionella risk assessment vs water testing', description: 'Understand the difference between assessing a water system, monitoring controls and testing samples for bacteria.', cardPrompt: 'Buy the evidence needed for the question rather than a generic sample package.', eyebrow: 'Comparison guide',
      intro: 'A risk assessment examines how the water system can support growth and expose people. Control monitoring checks whether operating measures remain within limits. Microbiological testing measures a sample at a particular place and time. These are related but not interchangeable.',
      decision: { heading: 'Start with the management question', summary: 'Use assessment to identify risks and controls, monitoring to check the control scheme, and sampling where guidance or circumstances give the result a defined purpose. Buying samples without a system assessment can leave asset, temperature, stagnation and responsibility gaps untouched.', checks: ['Is the system boundary and risk assessment current?', 'Which control limit or concern would a measurement or sample test?', 'Who will interpret the result and what action threshold applies?'], action: 'Ask the provider to state why each test is proposed, where it will be taken, which laboratory and method will be used and what happens after each possible result. Keep routine assessment and investigation work distinct.' },
      sections: [
        { heading: 'Risk assessment', body: 'The assessment maps assets and exposure, evaluates operating conditions and existing controls, and defines the written scheme. It determines which monitoring and testing are justified.', detail: 'Its output should remain useful between visits because the responsible person can see tasks, frequencies, limits, records and corrective actions.' },
        { heading: 'Control monitoring', body: 'Temperature checks, inspections, flushing, cleaning and other operating records show whether the selected control regime is being carried out and achieving its limits.', points: ['Named task owner', 'Defined frequency', 'Measurable limit', 'Recorded result', 'Corrective action for failure'] },
        { heading: 'Microbiological sampling', body: 'Sampling is appropriate for specified systems and situations, including investigation or verification questions identified by technical guidance. One result represents one sample and time.', detail: 'Require sample points, method, accredited analysis, interpretation and response actions. Do not treat a negative sample as proof that all parts of an uncontrolled system are safe.' },
      ], sources: [legionellaL8, legionellaHsg274, legionellaControl],
    },
  ],
  'pat-testing': [
    {
      path: '/pat-testing', title: 'PAT testing and electrical equipment maintenance', description: 'Decide whether equipment needs user checks, visual inspection, combined testing or another maintenance action.', cardPrompt: 'Turn equipment risk and use into a proportionate testing brief.', eyebrow: 'PAT testing overview',
      intro: 'Portable appliance testing is one way to check electrical equipment, but it is not an annual certificate required for every plug. The legal task is to maintain equipment so it does not cause danger, using checks, inspection and testing that match the equipment and its use.',
      decision: { heading: 'Buy a maintenance regime, not a sticker round', summary: 'Start with who controls the equipment, how it is used, the environment, damage history and protective class. That evidence decides which items need user checks, formal visual inspection, combined electrical tests or specialist work, and when each action should be repeated.', checks: ['Count equipment by type, location, owner and user rather than estimating plugs from floor area.', 'Separate office IT from moved tools, public-use appliances, extension leads and harsh-environment equipment.', 'Record faults, repairs, failed items, shutdown constraints and the evidence used to set each interval.'], action: 'Give every provider the same equipment counts and risk groups. Require an itemised register, agreed exclusions, test method, failed-item process and risk-based next-action advice instead of asking for a generic annual certificate.' },
      sections: [
        { heading: 'Legal maintenance duty', body: 'Regulation 4 of the Electricity at Work Regulations requires systems to be maintained so far as is reasonably practicable to prevent danger. HSE states that the regulations do not prescribe annual inspection or testing of appliances.', detail: 'The buyer should be able to explain why each equipment group receives user checks, formal visual inspection, combined testing, repair or another control. One interval applied to every item is not a risk assessment.' },
        { heading: 'Equipment boundary', body: 'The maintenance duty is not limited to small items described as portable. Movable, transportable, stationary, fixed, information-technology and extension-lead equipment can require different checks.', points: ['Who supplies and controls the item', 'Equipment class and construction', 'How often it is moved', 'Environment and foreseeable damage', 'Who uses it and how defects are reported'] },
        { heading: 'Useful records', body: 'HSE says labels and test records are not legal requirements in themselves, but they can support management and review. A useful register connects each item to its result, defect action and next planned check.', detail: 'A pass label does not prove that an unsuitable interval, missed equipment or unsafe user behaviour has been controlled. Keep the maintenance decision and defect process visible.' },
      ], sources: [electricityReg4, patFaq, patEquipment, patHsg107],
    },
    {
      path: '/pat-testing/do-i-need-pat-testing', title: 'Do I need PAT testing?', description: 'A decision aid for choosing user checks, visual inspections and combined electrical tests without assuming an annual rule.', cardPrompt: 'Use equipment risk rather than a blanket calendar interval.', eyebrow: 'Decision guide',
      intro: 'Employers must keep electrical equipment safe, but HSE says portable appliance testing is not compulsory as a named annual process. Combined inspection and testing becomes useful where equipment type, use, movement, environment or fault history means visual checks alone cannot give enough evidence.',
      decision: { heading: 'Use the equipment, environment and history test', summary: 'Frequently moved tools, earthed appliances, equipment used by the public, harsh conditions and repaired or damaged items can justify combined testing. Stable double-insulated office equipment in a clean, dry setting may need user checks or formal visual inspection rather than routine electrical testing.', checks: ['Can the equipment suffer damage through movement, moisture, dust, heat, impact or misuse?', 'Can a visual inspection reveal the relevant defects, or is an electrical measurement needed?', 'Do previous defects or test results show that the current frequency catches problems before danger arises?'], action: 'Group equipment by risk and document the maintenance method for each group. Where combined testing is justified, ask a competent person to set the method and interval, then review both using actual defect and test results.' },
      sections: [
        { heading: 'Lower-risk office equipment', body: 'HSE identifies many clean, dry office settings as lower risk. Desktop computers and other stable equipment should not be placed on an annual testing cycle without evidence that testing is needed.', detail: 'Formal visual inspection can find damaged plugs, cables, casings, cable grips, overheating and poor repairs. User reporting should remove suspect equipment from service between planned checks.' },
        { heading: 'Higher-risk equipment and use', body: 'Tools on construction sites, equipment hired to others, earthed appliances, extension leads and items moved or used by the public need a different maintenance decision.', points: ['Construction and industrial use', 'Wet, dusty or outdoor environments', 'Repeated movement or cable strain', 'Public, guest or tenant use', 'Repairs, failures or uncertain history'] },
        { heading: 'New equipment', body: 'HSE says new equipment should arrive in a safe condition and does not automatically need formal PAT testing before use. A simple visual check should confirm that it is not damaged.', detail: 'Record supplier instructions, equipment class and intended environment. Add the item to the maintenance regime with a future action based on risk rather than applying an inherited annual date.' },
      ], sources: [patFaq, patLowRisk, patEquipment, electricityReg4],
    },
    {
      path: '/pat-testing/cost', title: 'How much does PAT testing cost?', description: 'Understand how item count, minimum attendance, equipment type, access, reporting and multiple sites affect a PAT testing quote.', cardPrompt: 'Count equipment and quote the same deliverables to every provider.', eyebrow: 'Cost guide',
      intro: 'PAT testing is commonly priced through a minimum attendance charge plus an item rate that falls for larger batches. Price comparisons fail when one supplier counts every lead and power supply while another excludes fixed items, difficult shutdowns, repairs, retests or the itemised register.',
      decision: { heading: 'Price from an item register and access plan', summary: 'Count ordinary items, extension leads, multi-part equipment, fixed or stationary appliances, microwaves and assets that cannot be disconnected during working hours. State whether the price must include labels, results, minor repairs, failed-item isolation, retests and a usable digital register.', checks: ['Give providers an estimated item count by site and equipment group.', 'Identify access restrictions, occupied areas, shift work and equipment that needs planned shutdown.', 'Specify the register columns, failure notification, report delivery and treatment of items not located.'], action: 'Ask for the minimum charge, included item quantity, rate for additional items, fixed-equipment method, travel, parking, VAT, out-of-hours work and retests as separate lines. Compare the same scope before comparing totals.' },
      sections: [
        { heading: 'Published provider prices', body: 'Safety-PAT publishes a site-rate and per-item structure for its stated area. PAT Checked publishes a minimum call-out and volume bands in the Midlands. London PAT publishes fixed item-count packages for Inner London.', detail: 'These pages show that location, batch size and inclusions matter. They do not establish a national tariff, and the Vendor Atlas range is not a provider quotation.' },
        { heading: 'Vendor Atlas calculation', body: 'The calculator shows the attendance and register allowance, item count, specialist or shutdown-sensitive items, complex-site allowance and additional sites as separate factors.', points: ['Ordinary item count', 'Fixed or specialist equipment', 'Access and shutdown complexity', 'Separate site attendance', 'Normal-hours assumption'] },
        { heading: 'Scope exclusions', body: 'PAT testing does not replace fixed-wiring inspection, equipment repair, product safety work or a wider electrical risk assessment. Specialist medical, high-voltage or production equipment can need another method and competence.', detail: 'Require the provider to list untested, inaccessible and failed items. Repairs, replacement parts, microwave leakage checks and return visits should be priced or excluded in writing.' },
      ], sources: [patFaq, patEquipment, patHsg107],
    },
    {
      path: '/pat-testing/who-can-carry-out-pat-testing', title: 'Who can carry out PAT testing?', description: 'Check competence, equipment, method, insurance, records and defect handling before appointing a PAT testing provider.', cardPrompt: 'Match the named tester and method to the equipment risk.', eyebrow: 'Supplier guide',
      intro: 'HSE does not require every portable appliance tester to be an electrician. The person must be competent for the work they perform. Combined inspection and testing needs the right equipment, the ability to use it and the knowledge to interpret results and take safe action.',
      decision: { heading: 'Check the person, equipment and decision process', summary: 'Ask who will attend, what equipment groups they are competent to inspect, which test instruments they will use and how they decide the correct test for each item. Competence must cover safe isolation, result interpretation, failed-item action and any fixed or specialist equipment accepted in the scope.', checks: ['Request the named tester’s training, experience and authorisation for the equipment groups.', 'Check instrument identification, calibration arrangements and the proposed inspection and test sequence.', 'Review an example register showing results, failures, exclusions, repairs and next-action advice.'], action: 'Verify current insurance and any qualification or membership claims with the issuing body. State who may repair equipment, who decides whether a failed item returns to service and how urgent defects are reported before the tester leaves.' },
      sections: [
        { heading: 'Competence evidence', body: 'A course certificate alone does not show that the tester can classify equipment, select a suitable method, interpret readings or manage an unsafe result. Ask for recent work with comparable equipment and settings.', detail: 'Where fixed, specialist, medical or production equipment is included, require evidence for that work or remove it from the PAT scope and appoint the right specialist.' },
        { heading: 'Inspection and test method', body: 'Visual inspection remains part of the process because some defects cannot be detected by an instrument. The proposal should explain how equipment type, construction and environment affect the checks and tests.', points: ['Equipment identification and classification', 'Formal visual inspection', 'Suitable electrical tests', 'Safe shutdown and reconnection', 'Pass, fail and defect criteria'] },
        { heading: 'Provider evidence limits', body: 'Vendor Atlas records claims from provider pages, including stated coverage, prices and deliverables. That evidence does not approve the firm or prove the competence of the person assigned to a booking.', detail: 'Keep the appointment evidence: quotation, insurance certificate, named tester, agreed scope, exclusions, instrument details, register and failure actions.' },
      ], sources: [patFaq, patEquipment, patHsg107],
    },
    {
      path: '/pat-testing/pat-testing-vs-visual-inspection', title: 'PAT testing vs visual inspection', description: 'Understand what user checks, formal visual inspection and combined electrical testing each contribute to equipment safety.', cardPrompt: 'Choose the check that can find the relevant defect.', eyebrow: 'Comparison guide',
      intro: 'User checks, formal visual inspection and combined inspection and testing answer different questions. HSE says many faults are visible, while some defects require electrical measurements. A good maintenance regime selects the least intrusive action that still controls the real risk.',
      decision: { heading: 'Match the check to the defect and risk', summary: 'User checks catch obvious damage during normal work. Formal visual inspection uses a competent, structured examination, often with access to plugs and equipment details. Combined testing adds measurements where construction, use or possible internal faults justify them.', checks: ['Which foreseeable defects can a trained user see before use?', 'Which checks need equipment opened, classified or inspected by a competent person?', 'Which remaining faults require a suitable electrical measurement to detect?'], action: 'Write one maintenance table that names each equipment group, check type, responsible person, interval, failure action and review evidence. Use defects and test history to shorten or extend intervals instead of repeating the same cycle without review.' },
      sections: [
        { heading: 'User checks', body: 'Users can look for damaged plugs, loose cable grips, exposed conductors, damaged casings, overheating and unsuitable taped repairs before or during use. They should know how to report and isolate suspect equipment.', detail: 'User checks work between planned inspections. They do not authorise untrained people to open plugs, repair equipment or decide that damaged equipment is safe.' },
        { heading: 'Formal visual inspection', body: 'A structured inspection by a competent person can identify defects missed in everyday use and verify equipment type, plug, cable, fuse, casing, markings and suitability for the environment.', points: ['Identify the item and equipment class', 'Inspect cable, plug and enclosure', 'Check signs of heat, contamination or misuse', 'Record defects and action', 'Set or review the next interval'] },
        { heading: 'Combined inspection and testing', body: 'Electrical measurements add evidence where visual inspection cannot establish continued safety. The selected tests must suit the equipment and be interpreted by someone who understands the results.', detail: 'Do not assume that an instrument pass cancels a visible defect. HSE states that visual examination is an essential part of portable appliance testing.' },
      ], sources: [patFaq, patLowRisk, patEquipment, patHsg107],
    },
  ],
  tm44: [
    {
      path: '/tm44', title: 'TM44 air-conditioning inspections', description: 'Check the 12 kW threshold, understand the inspection and compare evidenced providers for buildings in England and Wales.', cardPrompt: 'Turn a plant schedule into a clear TM44 inspection brief.', eyebrow: 'TM44 overview',
      intro: 'TM44 inspections examine the energy efficiency of qualifying air-conditioning systems in England and Wales. The trigger is the combined effective rated output under common control, not the size of one room or the rating of one indoor unit in isolation.',
      decision: { heading: 'Add the system before testing the threshold', summary: 'A system with an effective rated output above 12 kW must be inspected by an accredited energy assessor. Several smaller units can form one system where they are controlled by one person in one building, so a plant list and control boundary are the useful starting evidence.', checks: ['List every air-conditioning unit, rated output, building and control arrangement.', 'Add the effective rated output of units that form one system under common control.', 'Find the previous report, lodgement reference, inspection date and unresolved recommendations.'], action: 'If the combined capacity is above 12 kW, or cannot be established reliably, send the same plant schedule and records to accredited assessors. Ask each provider to confirm the system boundary, assessor level, attendance scope, report and lodgement.' },
      sections: [
        { heading: 'What the inspection covers', body: 'The assessor reviews accessible refrigeration and air systems, controls, maintenance information, sizing and opportunities to improve efficiency. The report records findings and recommendations for the person controlling the system.', detail: 'The inspection is advisory on energy performance. It does not require every recommendation to be implemented, but the report should make the evidence, faults and potential improvements understandable.' },
        { heading: 'The five-year cycle', body: 'Qualifying systems must be inspected at intervals not exceeding five years. A new owner or tenant should obtain the current report where control of the system transfers.', points: ['Confirm the last inspection date', 'Keep the lodged report reference', 'Recheck the boundary after system changes', 'Do not substitute a service record for the TM44 report'] },
        { heading: 'Jurisdiction matters', body: 'This Vendor Atlas vertical applies the England and Wales rules and guidance. Scotland and Northern Ireland have separate regulatory arrangements.', detail: 'A provider may work across the UK, but the buyer should ask which national rules, register and lodgement route apply to the building address.' },
      ], sources: [tm44Guide, tm44Summary, epbRegulations],
    },
    {
      path: '/tm44/do-i-need-a-tm44-inspection', title: 'Do I need a TM44 inspection?', description: 'A decision aid for the 12 kW combined-capacity threshold and five-year inspection duty in England and Wales.', cardPrompt: 'Check capacity, control and the current report.', eyebrow: 'Decision guide',
      intro: 'The legal test is whether an air-conditioning system in England or Wales has an effective rated output above 12 kW. A building can cross that threshold through several smaller units, even when no single unit is rated above 12 kW.',
      decision: { heading: 'Check cooling, control and capacity', summary: 'Identify equipment that provides air conditioning, decide which units are under the same control in the building, then total their effective rated output. If the total exceeds 12 kW, an accredited energy assessor must inspect the system no more than five years after the previous inspection.', checks: ['Does the building contain mechanical air conditioning rather than ventilation or heating alone?', 'Do units under one control have a combined effective rated output above 12 kW?', 'Is there a lodged report dated within the previous five years?'], action: 'Where labels or maintenance records do not establish the capacity, ask a competent HVAC maintainer or accredited energy assessor to verify the inventory. Do not treat unknown capacity as a confirmed breach or assume that small individual units are outside scope.' },
      sections: [
        { heading: 'Several units can be one system', body: 'Official guidance treats one or more units in a building controlled by one person as an air-conditioning system. The threshold therefore requires an inventory and an explicit decision about common control.', detail: 'Ask the provider to show which units were counted, their outputs and why they were grouped. That evidence makes the conclusion reviewable after additions or replacement.' },
        { heading: 'Who holds the responsibility', body: 'The person who controls the technical functioning of the system is responsible for arranging inspection. This may be an owner, tenant or another party depending on the lease and operational control.', points: ['Check the lease and service responsibilities', 'Name the person controlling operation', 'Record which buildings and systems they control', 'Transfer the report when responsibility changes'] },
        { heading: 'What this finder cannot decide', body: 'The questionnaire cannot verify plant ratings, contractual control or the current accreditation of an assessor. It gives a procurement conclusion from the facts entered.', detail: 'Use the result to locate missing evidence and obtain a scoped inspection. It is not a legal determination or the required inspection itself.' },
      ], sources: [tm44Guide, tm44Summary, epbRegulations],
    },
    {
      path: '/tm44/cost', title: 'How much does a TM44 inspection cost?', description: 'Understand how unit count, central plant, records, access, system complexity and sites affect an indicative TM44 price.', cardPrompt: 'Compare the same system boundary and report deliverables.', eyebrow: 'Cost guide',
      intro: 'TM44 quotations depend on the number and type of systems, how equipment is grouped, central plant, access, documentation and report work. A starting price without the plant boundary is not a comparable quotation.',
      decision: { heading: 'Price the plant list and deliverable', summary: 'A useful quote states the number of indoor and outdoor units, chillers and air-handling units, the buildings and controls included, assessor level, site attendance, report, lodgement and exclusions. Complex central systems normally require more inspection and analysis than a small split-system portfolio.', checks: ['Count units and record available rated outputs and identifiers.', 'List chillers, AHUs, controls, inaccessible plant and separate buildings.', 'State whether a previous lodged report, plant schedule and maintenance records exist.'], action: 'Ask providers to separate inspection and lodgement from servicing, repairs, access equipment and follow-up consultancy. Compare VAT treatment and travel on the same basis, then retain the accepted system schedule with the appointment.' },
      sections: [
        { heading: 'Vendor Atlas calculation', body: 'The estimator uses visible allowances for assessor attendance and lodgement, each air-conditioning unit, central plant, complex systems, missing records and additional sites. It applies a stated spread to produce a planning range.', detail: 'The initial calibration uses prices published by AccuTemp, Robinsons Facilities Services and Heat Pump Installers London. It is not a regulated tariff, market average or supplier quotation.' },
        { heading: 'Published prices vary', body: 'Checked providers publish different starting prices and bands because their assumed site and system scopes differ. Low starting prices should be tested against unit limits, assessor level, travel, report lodgement and central plant.', points: ['System and unit limits', 'Level 3 or Level 4 capability', 'Report and register fee', 'Travel, VAT and access', 'Chiller and AHU additions'] },
        { heading: 'Keep maintenance separate', body: 'A provider may also maintain or repair the system. Those activities can supply useful records but are not the statutory TM44 inspection.', detail: 'Ask for a separate line for remedial work so the inspection result and commercial recommendation remain distinguishable.' },
      ], sources: [tm44Guide, tm44Summary, epbRegulations],
    },
    {
      path: '/tm44/who-can-carry-out-a-tm44-inspection', title: 'Who can carry out a TM44 inspection?', description: 'Check assessor accreditation, level, system experience, report lodgement, insurance and scope before appointment.', cardPrompt: 'Verify the named assessor, not only the company.', eyebrow: 'Supplier guide',
      intro: 'A qualifying air-conditioning inspection must be completed by an accredited energy assessor. The required assessor level and practical experience should match the system type and complexity, especially where central plant or larger systems are involved.',
      decision: { heading: 'Verify the named assessor and scheme entry', summary: 'A provider statement is useful evidence, but the appointment should identify the person who will inspect, their current accreditation scheme and level, and the systems they can assess. Check the register or scheme evidence before relying on the claim.', checks: ['Request the named assessor, accreditation scheme, certificate number and level.', 'Check recent experience with comparable split, VRF, chiller or AHU systems.', 'Confirm who attends, reviews, lodges and answers technical questions after the report.'], action: 'Keep a copy of the register check, quotation, insurance evidence, plant schedule and lodged report. Vendor Atlas records provider-source claims and matching reasons but does not approve providers or certify individual competence.' },
      sections: [
        { heading: 'Accreditation is mandatory', body: 'Official guidance states that only an accredited energy assessor can carry out the inspection. Ask for evidence that is current on the appointment date and covers the relevant complexity.', detail: 'Do not rely only on a company logo or general HVAC qualification. The named assessor and applicable accreditation route are the evidence that matters.' },
        { heading: 'Level and system experience', body: 'The assessor needs suitable capability for the plant involved. Central systems, chillers, AHUs and complex controls require different knowledge from a straightforward split-system site.', points: ['Plant type and capacity', 'Control strategy', 'Ventilation and air distribution', 'Maintenance information', 'Energy-performance recommendations'] },
        { heading: 'Report and lodgement', body: 'The quotation should say that the inspection report will be lodged and give the buyer the registered report or reference. It should also identify exclusions and inaccessible equipment.', detail: 'Ask how factual errors are corrected and who will explain recommendations. A report should remain useful to the person operating and improving the system.' },
      ], sources: [tm44Summary, tm44Guide, epbRegulations],
    },
    {
      path: '/tm44/tm44-vs-air-conditioning-maintenance', title: 'TM44 inspection vs air-conditioning maintenance', description: 'Understand the difference between the statutory energy inspection, routine maintenance and refrigerant or safety work.', cardPrompt: 'Buy each service for the evidence it should produce.', eyebrow: 'Comparison guide',
      intro: 'TM44 inspection and air-conditioning maintenance overlap in the equipment and records they examine, but they serve different purposes. One assesses energy performance and produces a lodged report; the other keeps equipment operating and addresses faults.',
      decision: { heading: 'Do not substitute one record for another', summary: 'A service sheet can support the TM44 assessor with plant condition and maintenance history, but it is not the accredited inspection report. Likewise, TM44 recommendations do not replace servicing, repair, refrigerant leak checks or a suitable workplace safety regime.', checks: ['Is the work being bought an accredited inspection, maintenance visit or repair?', 'Will it produce a lodged TM44 report, a service record or both?', 'Which faults and recommendations are included, excluded or separately priced?'], action: 'Schedule both activities around a shared plant inventory where practical, but issue separate scopes and accept separate deliverables. Keep the accredited assessor independent enough to explain the energy findings before awarding remedial work.' },
      sections: [
        { heading: 'TM44 inspection', body: 'The accredited assessor evaluates accessible plant, controls, sizing, maintenance information and energy-efficiency opportunities, then produces and lodges the inspection report.', detail: 'The report gives advice and identifies findings. It does not itself maintain, repair or recommission the equipment.' },
        { heading: 'Maintenance and repair', body: 'Routine maintenance cleans, adjusts, tests and repairs equipment according to its needs and manufacturer information. Its records can help explain operating condition and recurring faults.', points: ['Filters and heat exchangers', 'Fans, coils and drainage', 'Controls and set points', 'Refrigerant-system work', 'Faults and corrective action'] },
        { heading: 'Other duties remain separate', body: 'The TM44 report does not settle every environmental, refrigerant, electrical or workplace-safety requirement associated with an air-conditioning system.', detail: 'Ask the relevant specialist which additional duties apply and keep each source, responsible person, interval and record separate in the compliance schedule.' },
      ], sources: [tm44Guide, tm44Summary, epbRegulations],
    },
  ],
}

